class SyncOrganizationsResource(SyncGraphResource[Organization]):
    """V4 organizations endpoint: search, iterate, count, facets, group_by.

    ``get(id)`` reads the V3 by-id route because V4 has no by-id endpoints.
    """

    path = "v4/organizations"
    model = Organization
    filters_model = OrganizationsFilters

    def find_variants(
        self,
        names: Sequence[str],
        *,
        country: str | None = None,
        page_size: int | None = None,
    ) -> list[Organization]:
        """Search each name fragment and return deduplicated organizations.

        Records are deduplicated by exact ``id`` keeping the first match;
        ``pending_org_::`` records are kept on purpose. They carry
        organization-project links that the canonical merged record lost,
        which makes them the main source of undercounted org-project
        links, so callers decide how to merge them.
        """
        filters = {"country": country} if country else None
        found: dict[str, Organization] = {}
        for name in names:
            page = self.search(filters, query=name, page_size=page_size)
            for org in page.results:
                found.setdefault(org.id, org)
        return list(found.values())


class SyncPersonsResource(SyncGraphResource[Person]):
    """V4 persons endpoint: search, iterate, count, facets, group_by.

    ``get(id)`` reads the V3 by-id route because V4 has no by-id endpoints.
    Batch lookups by ORCID use an OR expression over ``ids.original``.
    """

    path = "v4/persons"
    model = Person
    filters_model = PersonsFilters
    batch_size = 50

    def record_keys(self, entity: Person, field: str) -> list[str]:
        if field == "ids.original":
            keys = [normalize_orcid(value) for value in entity.originalId]
            keys.extend(
                normalize_orcid(entry.value)
                for entry in entity.pid
                if entry.typeCode.lower() == "orcid" and entry.value
            )
            return list(dict.fromkeys(keys))
        return super().record_keys(entity, field)

    def batch_get_by_orcid(
        self,
        orcids: list[str] | tuple[str, ...],
        *,
        batch_size: int | None = None,
        concurrency: int = 4,
    ) -> dict[str, Person]:
        """Fetch person records for many ORCID iDs in bounded, concurrent chunks.

        Accepts any spelling ``bibliofabric.ids.normalize_orcid`` handles. Keys
        are hyphenated ORCID iDs; ORCIDs without a person record are absent from
        the result. The request goes out as ``filter=ids.original:a|b|c``.
        """
        normalized = list(dict.fromkeys(normalize_orcid(orcid) for orcid in orcids))
        return self.batch_get(
            normalized,
            field="ids.original",
            batch_size=batch_size,
            concurrency=concurrency,
        )


